/**
 * dsh-mcp-manager — servers/dispatch/impl/call/index.ts：ws_mcp_call 执行器（原
 * connection/runtime/middleware.ts:583-772 的搬迁；路由/封装分支与错误文案口径不变）。
 *
 * 为什么远端分支走 ctx.tools.execute（#767 S1-4d）：换引擎后官方运行时只导出
 * `Config / apply / inject / name`，底层 client 不外露，「拿一个 client 去 callTool」这条路
 * 不再存在。转发按设计 §5.3：合成子调用 id、透传 parent、喂 `value` 给既有投影。
 *
 * 为什么全部入参显式化：原实现依赖 McpMiddleware 的 this（units / disabledTools /
 * allServers / 转发登记表），搬进新域后这些状态仍归中间层持有，只能按引用递入；本域不落第二份。
 */
import type {
  ToolDefinition,
  ToolOutputDefinition,
  ToolExecutionInput,
} from "@deepseek-ai/dsh-tools";
import type { ServerState } from "../../../../../shared/interface.ts";
import type { DispatchCallInput, ToolExecutionResultLike } from "../../deps.ts";
import { redactMcpError } from "../redact/index.ts";

/**
 * 合成子调用 id。品牌串（`ToolCallId`）没有运行时构造器——它的 brand 函数住在 dsh-llm 的
 * 运行时，而本包对官方包只许 `import type`——所以只能 `as unknown as` 造。格式照宿主 PTC 的
 * 先例（`${exec.callId}:ptc:${n}`，dsh-tools/lib/index.js:1211）：留着父 id 前缀，
 * 日志归因时一眼看出这是谁派发的子调用；尾序号固定 1，因为每次 ws_mcp_call 只转发一个子调用。
 */
function subCallId(callId: ToolExecutionInput["callId"]): ToolExecutionInput["callId"] {
  return `${String(callId)}:mcp:1` as unknown as ToolExecutionInput["callId"];
}

/** dispatch 域的连接条目（经 input.units 取值，不另持连接表；结构约束写法——
 * 直接索引泛型 U 会 TS2536，故先收窄到含 connections 形态再取）。 */
type CallEntry =
  DispatchCallInput["units"] extends ReadonlyMap<string, infer U>
    ? U extends { connections: Map<string, infer V> }
      ? V
      : never
    : never;

/** 远端子调用入参：合成 callId、透传可选字段，并**不带 agent**。 */
export function remoteExecutionInput(
  input: DispatchCallInput,
  id: string,
  tool: string,
  args: unknown,
): ToolExecutionInput {
  return {
    callId: subCallId(input.callId),
    ...(input.rootCallId === undefined ? {} : { rootCallId: input.rootCallId }),
    name: input.registeredNameFor(id, tool),
    arguments: typeof args === "object" && args !== null ? args : {},
    // #767 笔 1b F4 收口：远端转发**不带 agent**。带了就等于把子调用挂回该 agent 的作用域，
    // 而本包已把 mcp__* 从每个 agent 的模型视野摘掉——自家转发会被自己那条 deny 一起打死。
    // 不带 agent 走全局面（guard 靠 parent ∈ forwarding 放行）；代价是官方执行器那次图片
    // 准入退化成文本，由本包自持的 image-admission 经 finalizeContent 补回来。
    ...(input.parent === undefined ? {} : { parent: input.parent }),
    // 宿主 executor 无条件读 signal.aborted（实测 §2.9-6：给 undefined 当场 TypeError），
    // 而调用方不保证带 signal——没有就现造一个。
    signal: input.signal ?? new AbortController().signal,
  };
}
/** 派发前视为「未就绪」的六态子集（failed / reconnecting / stopped / disabled）；无条目同判。 */
const NOT_DISPATCHABLE_STATES: ReadonlySet<ServerState | undefined> = new Set([
  "failed",
  "reconnecting",
  "stopped",
  "disabled",
  undefined,
]);

/** 未就绪三归因（次序承重）：用户禁用 > 后台重连中 > 其余未就绪。 */
export function notReadyError(
  fullName: string,
  status: ServerState | undefined,
  userDisabled: boolean,
): Error {
  if (userDisabled) {
    return new Error(
      `ws_mcp_call: server ${JSON.stringify(fullName)} 已被用户禁用；可先在 GUI「MCP」浮窗中重新连接`,
    );
  }
  if (status === "reconnecting") {
    return new Error(
      `ws_mcp_call: server ${JSON.stringify(fullName)} 连接失败、正在后台重连；请稍后重试或重新连接`,
    );
  }
  return new Error(
    `ws_mcp_call: server ${JSON.stringify(fullName)} 未连接或连接失败，请先 ws_mcp_search 或 ws_mcp_list 确认 server 已连接`,
  );
}

/** 条目就绪裁决：可派发则带条目返回，否则带该情形的错误。 */
type ReadinessVerdict = { ready: true; entry: CallEntry } | { ready: false; error: Error };

/**
 * 就绪裁决（B4 连带：六态补 reconnecting 后守卫须把「后台重连中」纳入未就绪——
 * 否则退避窗口内会照常派发，而该代际的工具面已不可信）。
 */
export function judgeEntryReadiness(
  fullName: string,
  server: string,
  userDisabled: boolean,
  entry: CallEntry | undefined,
): ReadinessVerdict {
  const status = entry?.status;
  if (NOT_DISPATCHABLE_STATES.has(status)) {
    return { ready: false, error: notReadyError(fullName, status, userDisabled) };
  }
  if (status === "connecting") {
    return {
      ready: false,
      error: new Error(
        `ws_mcp_call: server ${JSON.stringify(fullName)} 连接仍在进行，请稍后重试；连接完成后再调用`,
      ),
    };
  }
  if (entry === undefined) {
    return { ready: false, error: notReadyError(fullName, status, userDisabled) };
  }
  return { ready: true, entry };
}
/**
 * 封装 execute 的最小 exec 面：契约要完整 ToolRunContext，中间层只能给最小面
 * （agent 透传，session cwd 解析用）——经 unknown 中转（消费方封装定义只读 exec.agent）。
 */
export function wrappedExecContext(
  input: DispatchCallInput,
): Parameters<NonNullable<ToolDefinition["execute"]>>[1] {
  return { agent: input.agent } as unknown as Parameters<NonNullable<ToolDefinition["execute"]>>[1];
}

/** 封装结果投影：有 output.render 走渲染，否则按字符串/JSON 文本兜底。 */
export function wrappedContent(def: ToolDefinition, args: unknown, value: unknown) {
  if (typeof def.output?.render === "function") {
    return def.output.render(
      args,
      value as unknown as Parameters<NonNullable<ToolOutputDefinition["render"]>>[1],
    );
  }
  return [
    {
      type: "text",
      text: typeof value === "string" ? value : JSON.stringify(value ?? {}),
    },
  ];
}
/** 解析调用目标：回答「这通调用派得出去吗？」——全名格式 + 单元在册 + 条目就绪
 * （失败/重连中/停止/禁用/连接中各有去处，用户指引见各分支文案）；策略裁决与
 * 两条执行分支在外层（不同问题）。
 * @returns 目标全名解析、单元与就绪条目；不可达时抛错。 */
function resolveCallTarget(input: DispatchCallInput): {
  parsed: { root: string; server: string };
  entry: CallEntry;
} {
  const parsed = input.workspace.parseFullServerName(input.fullName);
  if (parsed === undefined) {
    throw new Error(
      `ws_mcp_call: unknown server ${JSON.stringify(input.fullName)}; 格式应为 @<root>/<server>`,
    );
  }
  const unit = input.units.get(parsed.root);
  if (unit === undefined) {
    throw new Error(
      `ws_mcp_call: 工作空间 ${JSON.stringify(parsed.root)} 未激活；请先 ws_mcp_search 或 ws_mcp_list`,
    );
  }
  const verdict = judgeEntryReadiness(
    input.fullName,
    parsed.server,
    unit.userDisabled.has(parsed.server),
    unit.connections.get(parsed.server),
  );
  if (!verdict.ready) throw verdict.error;
  return { parsed, entry: verdict.entry };
}

/** 执行封装直呼分支：回答「注入的封装定义怎么调？」——定义查找 + 超时兜底 +
 * output.render 投影（与 supervisor 封装分支 / dsh-tools 同口径）；路由、策略与
 * 远端转发不在此（不同问题）。
 * @returns 调用结果（content + 条件 structuredContent）；失败抛错（已脱敏）。 */
async function executeWrappedCall(
  input: DispatchCallInput,
  parsed: { root: string; server: string },
  tool: string,
  args: unknown,
  callBudgetMs: number,
  wrapped: ToolDefinition[],
): Promise<unknown> {
  const { pipeline, signal } = input;
  const def = wrapped.find((d) => d?.name === tool);
  if (def === undefined) {
    throw new Error(
      `ws_mcp_call: 工具 ${JSON.stringify(`${parsed.server}/${tool}`)} 不存在（封装定义服务器）`,
    );
  }
  try {
    // #413 QA P2-2：封装 execute 补超时兜底（与远端分支同预算 callBudgetMs，
    // 封装实现挂起时不无限等待）。
    const value = await pipeline.withTimeout(
      def.execute(typeof args === "object" && args !== null ? args : {}, wrappedExecContext(input)),
      callBudgetMs + 2000,
      `ws_mcp_call: 封装调用超时（${callBudgetMs}ms），可重试；若反复超时请检查插件状态`,
      signal,
    );
    const content = wrappedContent(def, args, value);
    // #512 共性问题：structuredContent 条件展开——封装 execute 返回 undefined
    // 时不落键，防显式 undefined 值键触发宿主 lossless JSON 校验失败（#381 同源）。
    return {
      content,
      ...(value !== undefined ? { structuredContent: value } : {}),
    };
  } catch (error) {
    if (signal?.aborted === true) throw signal.reason;
    throw new Error(
      redactMcpError(
        pipeline,
        input.allServers(),
        `ws_mcp_call: ${JSON.stringify(`${parsed.server}/${tool}`)} 封装调用失败：${pipeline.msgOf(error)}`,
      ),
    );
  }
}

/** 执行远端转发分支：回答「远端工具怎么调并收敛？」——装载就绪守卫 + 子调用合成 +
 * 超时兜底 + isError 收敛 + 白名单投影（stale 目录前置提示）；路由、策略与封装
 * 直呼不在此（不同问题）。
 * @returns 投影后的调用结果；失败抛错（已脱敏）。 */
async function executeRemoteCall(
  input: DispatchCallInput,
  parsed: { root: string; server: string },
  tool: string,
  args: unknown,
  entry: CallEntry,
  callBudgetMs: number,
  stale: boolean,
): Promise<unknown> {
  const { pipeline, signal } = input;
  // 装载尚未完成（账本键还没写回）时没有可派发的注册名。这不是旧的「client 缺失」就绪性
  // 判定：状态面已在上面把 connecting 挡掉，但官方等待窗口的 onState 与 mountServer 的返回
  // 之间还隔着微任务，状态可能已推进而 id 尚未写回——留一道并发窗口的兜底。
  const id = entry.id;
  if (id === undefined) {
    throw new Error(
      `ws_mcp_call: server ${JSON.stringify(input.fullName)} 未就绪（装载未完成）；请稍后重试或重新连接`,
    );
  }
  let result: ToolExecutionResultLike;
  try {
    result = await pipeline.withTimeout(
      input.execute(remoteExecutionInput(input, id, tool, args)),
      callBudgetMs + 2000,
      `ws_mcp_call: 调用超时（${callBudgetMs}ms），可重试；若反复超时请用 ws_mcp_detail 核对参数或检查服务器状态`,
      signal,
    );
  } catch (error) {
    if (signal?.aborted === true) throw signal.reason;
    throw new Error(
      redactMcpError(
        pipeline,
        input.allServers(),
        `ws_mcp_call: ${JSON.stringify(`${parsed.server}/${tool}`)} 调用失败：${pipeline.msgOf(error)}`,
      ),
    );
  }
  // isError 必须在上面 try 之外收敛（RECON 反例 4）：官方在 MCP isError:true 时**抛错**，
  // 套进那个 catch 会得到双层「调用失败：」；同时手工补回核对参数的引导句。
  if (result.isError === true) {
    throw new Error(
      redactMcpError(
        pipeline,
        input.allServers(),
        `ws_mcp_call: 远端工具返回错误：${result.error.message}；可先用 ws_mcp_detail 核对参数 schema 后重试`,
      ),
    );
  }
  // #512：远端结果经 call-result.ts 统一投影收敛（白名单清洗 + 无 content 兜底），与
  // supervisor（mcp__ 直呼）/ 官方 dsh-mcp-client createExecutor 同一契约——不再裸透传
  // resultObj，Python SDK 必带的 isError:false / _meta 等字段不再外泄进工具契约。
  // 换引擎后喂进来的是官方结果里的 `value`（远端原始结果，实测 §2.9-5），故与旧链路
  // 逐字节等价；`errorText` 分支因此在新链路上不可达（isError 已在上面收敛），保留是
  // 为了不把「投影形态」的两种协议违规入口拆成两处实现——有意变更，已在 PR 台账登记。
  const projected = pipeline.projectCallToolResult(result.value, {
    errorText: (content) =>
      `ws_mcp_call: 远端工具返回错误：${pipeline.msgOf(content)}；可先用 ws_mcp_detail 核对参数 schema 后重试`,
    fallbackText: (r) => {
      const raw =
        typeof r === "object" && r !== null && "content" in r
          ? (r as { content?: unknown }).content
          : undefined;
      return raw !== undefined && !Array.isArray(raw)
        ? pipeline.msgOf(raw)
        : pipeline.defaultCallResultFallbackText(r);
    },
  });
  if (stale) {
    // schema 可能已过期：结果前置提示（投影后的白名单结构，仅扩 content）。
    const hint = {
      type: "text",
      text: "（提示：本工具目录已过期，schema 可能已变更，请重新 ws_mcp_search）",
    };
    return {
      content: [hint, ...projected.content],
      ...(projected.structuredContent !== undefined
        ? { structuredContent: projected.structuredContent }
        : {}),
    };
  }
  return projected;
}

/** 执行一次 ws_mcp_call：路由一致性校验 → 策略裁决 → 封装直呼 / 远端转发两条分支。 */
export async function executeMcpCall(input: DispatchCallInput): Promise<unknown> {
  const { pipeline, workspace } = input;
  const { parsed, entry } = resolveCallTarget(input);
  const tool = workspace.normalizeToolName(parsed.server, input.toolRaw);
  // 工具级禁用（P0-1 三入口统一走 isToolDenied；#767 笔 2 后这是唯一裁决）。
  const policyKey = workspace.fullServerName(parsed.root, parsed.server);
  if (pipeline.isToolDenied(input.disabledTools, policyKey, tool)) {
    throw new Error(pipeline.toolDisabledReason(policyKey, tool));
  }
  const catalog = input.catalogEntryFor(parsed.server);
  const stale =
    catalog !== undefined &&
    catalog.unavailable === undefined &&
    Date.now() - catalog.discoveredAt > input.catalogTtlMs;
  if (stale) {
    // stale：仍可调用（目录只是提示），但 schema 可能过期——在结果前置提示。
  }
  const args = pipeline.normalizeArguments(input.rawArgs);
  // B18/D6：调用预算读 server.toolCallTimeoutMs（缺省 DEFAULT_TOOL_CALL_TIMEOUT_MS=15s），
  // withTimeout 兜底统一 +2s——两路径（supervisor SDK timeoutMs 无兜底）预算
  // 差异写入两路径契约测试的差异面签名。
  const callBudgetMs = entry.server?.toolCallTimeoutMs ?? input.defaultCallTimeoutMs;
  // #413 封装直呼分支：runtime 注入的封装定义服务器（toolDefinitions）——
  // execute 为调用方 JS（不经远端 client.callTool）。禁用/策略已在上面统一
  // 裁决（isToolDenied），此处直接调调用方 execute；输出经封装 output.render
  // 投影为 ContentBlock[]（与 supervisor 封装分支 / dsh-tools 同口径）。
  const wrapped = entry.server?.toolDefinitions;
  if (Array.isArray(wrapped)) {
    return executeWrappedCall(input, parsed, tool, args, callBudgetMs, wrapped);
  }
  return executeRemoteCall(input, parsed, tool, args, entry, callBudgetMs, stale);
}

/**
 * dsh-mcp-manager — servers/dispatch/impl/redact/index.ts：调用错误文案的凭据脱敏出口。
 *
 * 为什么独立一块而不是复用 middleware 的 `redact`：那一个的消费面是连接/发现路径（不属本域），
 * 两者共用的底层是 pipeline 的 `createRedactor`——各自一个薄封装，避免两块互相直引。
 *
 * 官方 dsh-mcp-client 不做错误文案脱敏，换引擎后这一层仍必须由我方保留（设计 §2.5）；脱敏源（#770-8 全集快照
 * （全局 store + 全部 projectStores 缓存 + runtimeRegistry，含 disabled/unconnected）由调用方递入取值结果（中间层转供宿主 redactionServers，与 manager/middleware 同一秘密源），本域不持有服务器表。
 */
import type { ServerConfig } from "../../../../config/interface.ts";
import type { DispatchPipelinePort } from "../../deps.ts";

/** 把调用错误文案里的凭据抹掉；服务器表按值传入，每次现建脱敏器（与旧 `hostRedact` 同口径）。 */
export function redactMcpError(
  pipeline: DispatchPipelinePort,
  servers: readonly ServerConfig[],
  text: string,
): string {
  const redactor = pipeline.createRedactor([...servers]);
  return redactor(new Error(text));
}

/**
 * dsh-mcp-manager — servers/lifecycle/impl/ledger/index.ts：装载账本（确定性回收链，§1.5）。
 *
 * 装载实例不能交给 loader 的 entry 树持有：`EntryTree.create` 末行 `tree.write()` 会把运行期
 * command / args / env（含凭据模板展开后的明文）写回用户 profile。所以官方实例由我方账本持有、
 * 回收也由我方负责——这是两条回收链的主链，兜底链是 `bindHost` 里 `ctx.effect` 注册的 dispose。
 *
 * 已知缺口（照 §1.5 写进实现）：`DomainSpec.release(): void` 是同步签名，而官方 `dispose()` 会
 * await 首次连接尝试的在途 Promise（挂死的服务器可能等到 SDK 的 60s initialize 超时）。
 * 因此 `release()` 与单键的 `releaseOne()` 都只**发起** dispose 并把 Promise 收进 pendingDisposals，
 * 另开 `flushDisposals()` 供测试与真机验证显式等待；需要等结算的单键路径用 `dispose()`。
 *
 * 键由调用方给（id 生成与 `(scope,name)→id` 表归 workspace 域，§2.6 裁定 B）：本域不生成 id，
 * 也不把键写进 MountedPlugin——端口因此对配置与命名保持无感知。同一键未释放前重复 mount
 * 属编程错误，不等官方那句 `serverName is already in use`（那是第二道闸，不是第一道）。
 */
import type { MountedPlugin, OfficialPluginModule } from "../../../../shared/interface.ts";
import { lifecyclePorts } from "../service/index.ts";

/** 账本条目：一次装载留下的全部我方痕迹（模块与配置只为排查用，不参与回收裁决）。 */
export interface LedgerEntry {
  readonly key: string;
  readonly module: OfficialPluginModule;
  readonly config: unknown;
  readonly handle: MountedPlugin;
}

class MountLedger {
  private readonly entries = new Map<string, LedgerEntry>();
  /** 释放后待结算的 dispose：只收不 await，见文件头「已知缺口」。 */
  private pending: Promise<void>[] = [];

  /** 记账并**发起**装载：先查键再装，撞键当场抛（早失败 + 判词点名键）。 */
  mount(key: string, module: OfficialPluginModule, config: unknown): LedgerEntry {
    if (this.entries.has(key)) {
      throw new Error(
        `dsh-mcp-manager: servers/lifecycle 账本已有键 ${key}——同一 serverName 未释放前不得重复 mount`,
      );
    }
    const handle = lifecyclePorts.get().loader.mount(module, config);
    const entry: LedgerEntry = { key, module, config, handle };
    this.entries.set(key, entry);
    return entry;
  }

  get(key: string): LedgerEntry | undefined {
    return this.entries.get(key);
  }

  get size(): number {
    return this.entries.size;
  }

  /** 该条目是否仍是账本当前代际：被替换或已移除都不算——晚到结算据此丢弃（代际守卫）。 */
  isCurrent(entry: LedgerEntry): boolean {
    return this.entries.get(entry.key) === entry;
  }

  /**
   * 单键释放，**只发起不等结算**：摘账同步生效（`isCurrent` 立刻为假），dispose 收进既有
   * pending。拆除路径用它——见文件头「已知缺口」；要等结算的重建路径用 `dispose()`。
   */
  releaseOne(key: string): void {
    const entry = this.entries.get(key);
    if (entry === undefined) return;
    this.entries.delete(key);
    const disposal = entry.handle.dispose();
    // 没有任何调用方 await 这个 promise，不吞掉拒绝就会变成 unhandled rejection 打崩进程；
    // pending 里仍放**原 promise**——上抛语义留给 flushDisposals（吞掉错因等于把泄漏变成静默）。
    void disposal.catch(() => {});
    this.pending.push(disposal);
  }

  /** 单键释放：先摘账（同步生效，isCurrent 立刻为假）再等句柄结算。 */
  async dispose(key: string): Promise<void> {
    const entry = this.entries.get(key);
    if (entry === undefined) return;
    this.entries.delete(key);
    await entry.handle.dispose();
  }

  /** 域卸载：逐条摘账并发起 dispose，不等结算（见文件头「已知缺口」）。 */
  release(): void {
    const entries = [...this.entries.values()];
    this.entries.clear();
    for (const entry of entries) this.pending.push(entry.handle.dispose());
  }

  /**
   * 等待已发起的 dispose 全部落定。任一失败如实上抛：兜底链保证的是「卸载不卡住」，
   * 不是「dispose 永不失败」，吞掉错因会让泄漏变成静默。
   */
  async flushDisposals(): Promise<void> {
    const pending = this.pending;
    this.pending = [];
    const settled = await Promise.allSettled(pending);
    const rejected = settled.find((result) => result.status === "rejected");
    if (rejected !== undefined && rejected.status === "rejected") throw rejected.reason;
  }
}

/** 本域唯一的账本实例：类不外放，外部 new 不出第二份账。 */
export const mountLedger = new MountLedger();

/**
 * dsh-mcp-manager — servers/lifecycle/impl/logs/index.ts：官方日志的归属与诊断文案（裁定 M）。
 *
 * 为什么本块存在：换引擎后官方不暴露任何状态 API——成功连接零日志，失败与放弃重连才在宿主日志
 * 上说话，且每条都带 `mcp-client(<serverName>)` 前缀。而 serverName **就是我方分配的 id**，
 * 所以归属是精确匹配而不是猜时间窗：没有这一块，「首连失败」在用户侧只剩我方那两段判词。
 *
 * 为什么不做成常驻订阅：日志的价值集中在装载窗口内（首连与首次发现都结算在官方 ready 之前），
 * 窗口结束即摘除——常驻订阅会让每个实例都挂一个导出器，而它唯一能多做的事是收事后噪音。
 *
 * 为什么截断：这些文案会进状态面（汇总 / /health / GUI），官方一次失败可能连打数条，原样透传
 * 会把一个状态字段撑成日志转储。
 */
import type { LogRecord, LogsPort } from "../../../../shared/interface.ts";
import { OFFICIAL_MCP_CLIENT_LOG_NAME } from "../../../../shared/interface.ts";

/** 进诊断文案的官方日志条数上限（取末 N 条）。 */
const MAX_DIAGNOSTIC_LINES = 3;
/** 单条官方日志进文案的字符上限。 */
const MAX_DIAGNOSTIC_CHARS = 240;

/**
 * 取一条日志记录的可读文本。
 *
 * 只认官方客户端这个记录名：域内导出器收的是**全宿主**的日志，不过滤就等于把别的插件的噪音
 * 记到本实例头上。官方把文案放在字符串参数里（其余参数是结构化上下文），故只拼字符串段。
 */
export function officialLogText(record: LogRecord): string | undefined {
  if (record.name !== OFFICIAL_MCP_CLIENT_LOG_NAME) return undefined;
  const text = record.args
    .filter((arg): arg is string => typeof arg === "string")
    .join(" ")
    .trim();
  return text === "" ? undefined : text;
}

/**
 * 把一条官方日志归到某个实例：官方文案形如 `mcp-client(<serverName>): …`。
 *
 * 按**全等前缀**匹配而不是包含：id 是随机短串，但用户可能配出名字互为前缀的服务器，包含匹配会
 * 让 A 的话记到 B 头上——错归属比没有归属更坏（它会指向错误的排查对象）。
 */
export function attributeOfficialLog(text: string, serverName: string): string | undefined {
  const prefix = `${OFFICIAL_MCP_CLIENT_LOG_NAME}(${serverName})`;
  if (!text.startsWith(prefix)) return undefined;
  const rest = text
    .slice(prefix.length)
    .replace(/^[\s:：]*/u, "")
    .trim();
  return rest === "" ? undefined : rest;
}

/** 单条文案的形态收敛：折叠换行（状态面是单行字段）并按字符上限截断。 */
function trimLine(line: string): string {
  const flat = line.replace(/\s+/gu, " ").trim();
  return flat.length > MAX_DIAGNOSTIC_CHARS ? `${flat.slice(0, MAX_DIAGNOSTIC_CHARS)}…` : flat;
}

/**
 * 把收集到的官方原文拼成可挂进状态面的一段文案；一条都没有时返回 undefined（不占字段）。
 *
 * 报出总条数与实际取用条数：只给末 N 条而不说省略了多少，等于让读的人以为官方只说了这些。
 */
export function diagnosticText(lines: readonly string[]): string | undefined {
  const kept = lines
    .filter((line) => line.trim() !== "")
    .slice(-MAX_DIAGNOSTIC_LINES)
    .map(trimLine);
  if (kept.length === 0) return undefined;
  const omitted = lines.length - kept.length;
  const tail = omitted > 0 ? `（共 ${lines.length} 条，取末 ${kept.length} 条）` : "";
  return `官方日志${tail}：${kept.join(" | ")}`;
}

/** 一次装载窗口的日志收集面：窗口结束调 `stop()` 摘除导出器。 */
export interface OfficialLogCollector {
  /** 到目前为止归属到本实例的原文（按到达顺序）。 */
  lines(): readonly string[];
  /** 摘除导出器；可重复调用（第二次是空操作）。 */
  stop(): void;
}

/**
 * 装一个只服务于某个实例的收集器。
 *
 * 摘除失败一律吞掉：诊断功能的存在意义是**减少静默**，它自己绝不能变成新的失败源——装载窗口的
 * `finally` 里抛错会把一次已经结算好的装载改写成失败。
 */
export function collectOfficialLogs(logs: LogsPort, serverName: string): OfficialLogCollector {
  const lines: string[] = [];
  let stopped = false;
  const dispose = logs.capture((record) => {
    const text = officialLogText(record);
    if (text === undefined) return;
    const attributed = attributeOfficialLog(text, serverName);
    if (attributed === undefined) return;
    lines.push(attributed);
  });
  return {
    lines: () => lines,
    stop(): void {
      if (stopped) return;
      stopped = true;
      try {
        dispose();
      } catch {
        // 见函数注释：诊断面不得把装载改写成失败。
      }
    },
  };
}

/**
 * dsh-mcp-manager — servers/lifecycle/impl/mount/index.ts：一个 (root, server) 的真装载（§3.4）。
 *
 * 装载链：workspace 端口取 id → 构造官方 Config（env / headers 经 config 端口预展开）→ loader
 * 按包名解析官方插件 → 账本记账装载 → 跑等待窗口投影六态。官方包不在 catalog、仓库内不可解析，
 * 故包名只能是说明符（见共享层的 OFFICIAL_MCP_CLIENT_SPECIFIER），模块形状由 LoaderPort 给。
 *
 * 为什么 id 不在本块生成：官方 serverName 在 `scopeOf(ctx) ?? ctx.root` 这个**整个应用根**上
 * 活体预留，同 owner 重名当场抛；而「同一 bare 名在全局与某项目都配」是常见写法。id 与
 * `(scope,name)→id` 表归 workspace 域（767-v6-STAGED-PLAN §2.6 裁定 B），本块只消费
 * `idFor(root, name)`——scope 传 root，跨 root 同名因此各自成条。
 *
 * 为什么 Config 逐字段显式构造而不透传配置对象：官方 Config 是 stdio / streamable-http 联合，
 * 多带一个不属于该 transport 的键会被 schema 拒；`serverName` / `failOnStartupError` /
 * `toolCallTimeoutMs` 三个字段还各有一条口径（见 officialMcpConfig 内注释）。
 *
 * 为什么 env / headers 在这里展开：模板落盘、交给官方前才展开是本插件的凭据面不变量——在
 * normalizeServer 里展开等于把明文凭据随下一次 store.save() 写进 storePath（设计 §2.4）。
 */
import type { ServerConfig } from "../../../../config/interface.ts";
import {
  DEFAULT_TOOL_CALL_TIMEOUT_MS,
  OFFICIAL_MCP_CLIENT_SPECIFIER,
} from "../../../../shared/interface.ts";
import type { ServerState } from "../../../../../shared/interface.ts";
import type { ToolsRegistryPort } from "../../deps.ts";
import { mountLedger } from "../ledger/index.ts";
import type { LedgerEntry } from "../ledger/index.ts";
import { collectOfficialLogs } from "../logs/index.ts";
import { lifecyclePorts } from "../service/index.ts";
import { awaitMountWindow } from "../timeout/index.ts";
import type { MountWindowOutcome } from "../timeout/index.ts";

/** 官方 Config 的公共字段（自持声明：官方包不在 catalog，类型面取不到，形状只在这里写一次）。 */
interface OfficialConfigCommon {
  /** 交给官方的 serverName；本包用 (scope,name) 分配的随机短串（进 `mcp__<id>__` 前缀）。 */
  readonly serverName: string;
  /** 单次工具调用预算。必须显式给：官方默认 60s，缺省会把本插件的 15s 口径放大四倍。 */
  readonly toolCallTimeoutMs: number;
  /** 官方重连策略；未知键已在 config 域归一化期丢弃（官方对未知键直接抛错）。 */
  readonly reconnect: Readonly<Record<string, unknown>>;
  /** 恒 false：首连失败不得卸载实例，理由见 officialMcpConfig 内注释。 */
  readonly failOnStartupError: false;
}

/**
 * 官方 dsh-mcp-client 的 Config 形状。
 *
 * 写成联合而不是「全可选字段的对象」：stdio 与 streamable-http 的字段互斥，用联合让
 * 「给 stdio 带上 url」这类错误在编译期就出不去。
 */
export type OfficialMcpConfig =
  | (OfficialConfigCommon & {
      readonly transport: "stdio";
      readonly command: string;
      readonly args: readonly string[];
      readonly env: Readonly<Record<string, string>>;
      readonly cwd: string;
    })
  | (OfficialConfigCommon & {
      readonly transport: "streamable-http";
      readonly url: string;
      readonly headers: Readonly<Record<string, string>>;
    });

/**
 * 把一条归一化后的服务器配置映射成官方 Config（设计 §2.1 的逐字段表）。
 *
 * 展开函数按参数递入而不是块内现取端口：映射是纯函数，能脱离装配单独测「模板 → 字面量」。
 */
export function officialMcpConfig(
  server: ServerConfig,
  id: string,
  expandServerEnv: (server: ServerConfig) => ServerConfig,
): OfficialMcpConfig {
  const expanded = expandServerEnv(server);
  const common = officialConfigCommon(server, id);
  if (server.transport === "stdio") {
    return stdioOfficialConfig(server, expanded, common);
  }
  return httpOfficialConfig(server, expanded, common);
}

/** 三个 transport 无关字段的公共段（serverName / failOnStartupError / toolCallTimeoutMs
 *  各有一条口径，见调用处注释）。 */
function officialConfigCommon(server: ServerConfig, id: string): OfficialConfigCommon {
  return {
    serverName: id,
    // 恒 false（§3.3）：置 true 会让首连失败直接杀掉实例、官方后台重连随之被回收，等于放弃
    // 「常驻重连」语义；failed 因此是软失败——实例仍在，只是拿不到具体错因（§3.2-1）。
    failOnStartupError: false,
    // 官方默认 60s；本插件的 DEFAULT_TOOL_CALL_TIMEOUT_MS 是 15s，必须显式覆盖。
    toolCallTimeoutMs: server.toolCallTimeoutMs ?? DEFAULT_TOOL_CALL_TIMEOUT_MS,
    // 缺失时给 {}：官方 resolveReconnectPolicy 先补默认值再判关系，本块不重抄一份默认值表。
    reconnect: server.reconnect ?? {},
  };
}

/** stdio 支：command 必填，其余三项显式给默认值。 */
function stdioOfficialConfig(
  server: ServerConfig,
  expanded: ServerConfig,
  common: OfficialConfigCommon,
): OfficialMcpConfig {
  if (typeof server.command !== "string" || server.command === "") {
    throw new Error(
      "dsh-mcp-manager: stdio 服务器缺 command，拒绝装载（配置面应已由 normalizeServer 保证非空）",
    );
  }
  return {
    transport: "stdio",
    command: server.command,
    // 三个字段都显式给默认值：官方 schema 虽有默认，但依赖它等于把「配置里到底写没写」与官方
    // rc 的内部实现绑在一起（§2.1 表）。cwd 的空串不能给 undefined——见 §2.3。
    args: server.args ?? [],
    env: expanded.env ?? {},
    cwd: server.cwd ?? "",
    ...common,
  };
}

/** streamable-http 支：url 必填，headers 取展开后的形态。 */
function httpOfficialConfig(
  server: ServerConfig,
  expanded: ServerConfig,
  common: OfficialConfigCommon,
): OfficialMcpConfig {
  if (typeof server.url !== "string" || server.url === "") {
    throw new Error(
      "dsh-mcp-manager: streamable-http 服务器缺 url，拒绝装载（配置面应已由 normalizeServer 保证非空）",
    );
  }
  return {
    transport: "streamable-http",
    url: server.url,
    headers: expanded.headers ?? {},
    ...common,
  };
}

/** 装载入参：一个 (root, server) 的全部外部输入（本域不自持调用方的状态）。 */
export interface MountServerInput {
  /** 工作空间根（`@<root>/<server>` 的 root，也是 id 表的 scope）。 */
  readonly root: string;
  /** 归一化后的服务器配置；env / headers 仍是模板形态，展开在本块内做。 */
  readonly server: ServerConfig;
  /** 连接等待预算（ms）；缺省取共享层 CONNECT_TIMEOUT_MS（测试用小预算驱动真超时）。 */
  readonly connectTimeoutMs?: number;
  /** 状态投影出口：窗口在起点与结算点各回调一次；被丢弃的结算不回调。 */
  readonly onState: (state: ServerState) => void;
}

/** 一次装载的结果：id 与账本条目供调用方后续定位/拆除，outcome 是等待窗口的结算。 */
export interface MountServerResult {
  readonly id: string;
  readonly entry: LedgerEntry;
  readonly outcome: MountWindowOutcome;
}

/**
 * 装载一个 (root, server)：取 id → 构造官方 Config → 解析模块 → 账本记账挂载 → 跑等待窗口。
 *
 * 三件本函数**刻意不做**的事：不裁决 `enabled === false`（配置面语义归调用方，§2.2-1）、
 * 不在窗口失败时 dispose（连接失败的实例保留给官方后台重连，§3.4 步骤 5a）、不吞装载期异常
 * （解析失败 / 账本撞键一律上抛，避免装配静默少装一个服务器）。
 */
export async function mountServer(input: MountServerInput): Promise<MountServerResult> {
  const { loader, workspace, config, tools, logs } = lifecyclePorts.get();
  const id = workspace.idFor(input.root, input.server.name);
  const officialConfig = officialMcpConfig(input.server, id, config.expandServerEnv);
  const module = await loader.load(OFFICIAL_MCP_CLIENT_SPECIFIER);
  const entry = mountLedger.mount(id, module, officialConfig);
  // 收集器只包住等待窗口：首连与首次发现都结算在官方 ready 之前，窗口内的原话就是这次装载的
  // 全部错因；窗口结束即摘除，常驻订阅只会让每个实例都挂一个导出器去收事后噪音。
  const collected = collectOfficialLogs(logs, id);
  let outcome: MountWindowOutcome;
  try {
    outcome = await awaitMountWindow({
      id,
      handle: entry.handle,
      // 代际守卫读账本：本条目被 dispose 或顶替之后到达的结算一律作废（§3.4 步骤 6）。
      isCurrent: () => mountLedger.isCurrent(entry),
      hasTools: (candidate) => hasRegisteredTools(tools, candidate),
      diagnostics: collected.lines,
      onState: input.onState,
      ...(input.connectTimeoutMs === undefined ? {} : { connectTimeoutMs: input.connectTimeoutMs }),
    });
  } finally {
    // 必须 finally：窗口抛错时更要摘，否则一个失败的实例会永久占着宿主日志面。
    collected.stop();
  }
  return { id, entry, outcome };
}

/**
 * 工具注册面探测：官方把该服务器的工具注册成 `mcp__<id>__<tool>`，前缀命中即「该 id 下有工具」。
 *
 * 只按前缀判而不是查某个具体工具名：工具清单由远端决定，本包在装载期一个名字都不知道；而
 * 名字里的 id 是本包自己分配的，前缀因此是「这个实例注册成功」的可靠证据（§3.1 输入面 B）。
 */
function hasRegisteredTools(tools: ToolsRegistryPort, id: string): boolean {
  const prefix = `mcp__${id}__`;
  return tools.schemas().some((schema) => schema.name.startsWith(prefix));
}

/**
 * dsh-mcp-manager — servers/lifecycle/impl/service/index.ts：装载生命周期域端口持有者。
 *
 * 域内实现经 `lifecyclePorts.get()` 取数，写入只发生在组合根入口顶层的 `installLifecycle`
 * （本片不接线，见 767-v6-STAGED-PLAN §3 阶段表）。形态照 `pipeline/impl/service/` 与
 * `connection/runtime/impl/service/`：模块级只有一个 `const` 实例、状态收进实例字段（I9），
 * 装配与复位只经方法（方法内赋值）。
 */
import type { LifecycleDeps } from "../../deps.ts";

/** 装载生命周期域端口表：装配一次、域内多处读。 */
class LifecyclePorts {
  /** 未装配时保持 undefined——「没装配」与「装配了空实现」必须可区分（I6）。 */
  private deps: LifecycleDeps | undefined;

  /** 装配：组合根递入静态模块引用；重复装配是编程错误，当场暴露。 */
  install(deps: LifecycleDeps): void {
    if (this.deps !== undefined)
      throw new Error("dsh-mcp-manager: servers/lifecycle 域只能装配一次");
    this.deps = deps;
  }

  /** 卸载：只复位装配标记，本域的活资源（装载账本）由 `releaseLifecycle` 另行回收。 */
  release(): void {
    this.deps = undefined;
  }

  /**
   * 域内取数的唯一入口。未装配即抛错而不是回落默认值：默认值会让「组合根漏装」表现成
   * 装载静默失败在没有 loader 的空实现上，症状与本插件毫无字面关联。
   */
  get(): LifecycleDeps {
    const deps = this.deps;
    if (deps === undefined) {
      throw new Error(
        "dsh-mcp-manager: servers/lifecycle 域未装配——组合根未在入口调用 installLifecycle（src/index.ts）",
      );
    }
    return deps;
  }
}

/** 本域唯一的装配实例：类不外放，外部 new 不出第二份端口表。 */
export const lifecyclePorts = new LifecyclePorts();

/**
 * dsh-mcp-manager — servers/lifecycle/impl/state/index.ts：六态投影（纯函数）。
 *
 * 官方 dsh-mcp-client **不暴露任何状态 API**（运行时只导出 Config / apply / inject / name），
 * 所以六态只能由「我方动作 + 工具注册面 + 我方超时封装」投影，而不是读官方内部状态。词表的
 * 物理定义在 src/shared/status.ts（跨端契约：summary().counts 的键序与客户端分组共用同一份），
 * 本文件不另造词表、只投影。
 *
 * 三条不可观测性（降级表述写在这里，因为投影口径由此确定）：
 * 1. **首连失败的具体 cause 拿不到**。官方在 failOnStartupError:false 下不抛（apply 正常
 *    resolve），connection.ready 的 {error} 只回到官方内部；改用 true 换 cause 会让失败的
 *    fiber 直接 FAILED、其 ctx.effect 被回收，官方后台重连随之消失。故 failed 携带的 error
 *    一律是我方文案，不含官方原始错因。
 * 2. **重连次数 / 退避剩余 / 放弃时点不可观测**。官方只在日志里出这些信息（connection attempt
 *    failed / retrying in Nms / reconnect stopped），而文案属官方内部实现、rc 内可变——状态机
 *    **不建在日志文案上**。failed 的判定用「工具前缀消失且无进一步变化」，不用「第 N 次 warn」。
 * 3. **reconnecting 窗口本身无信号**。官方断线瞬间不注销工具（工具在下次 syncTools swap 或
 *    dispose 才换），「工具还在 = 正在重连」与「工具还在 = 连接正常」不可区分。故本态只在
 *    **可判时点**投影（调用转发失败且错因来自连接层、主动低频注册面比对、切回前台重建期间）；
 *    其余时点投影为 connected，而实际链路可能已断——这是换引擎的既知代价。
 */
import { SERVER_STATES } from "../../../../../shared/interface.ts";
import type { ServerState } from "../../../../../shared/interface.ts";

/** 投影输入：三个输入面的快照，全部由调用方读取后递进来（本文件不持有状态）。 */
export interface ServerStateInput {
  /** 配置面启用（server.enabled === false 时为 false）。 */
  readonly enabled: boolean;
  /** 用户持久化禁用（配置面之外的第二个 disabled 来源）。 */
  readonly userDisabled: boolean;
  /** 我方已发起拆除：用户 disconnect / remove / update 拆旧代际，或本插件卸载。 */
  readonly tornDown: boolean;
  /** 已发起 mount（我方动作面）。 */
  readonly mountStarted: boolean;
  /** ready 已 settle（成功与失败都 settle）。 */
  readonly readySettled: boolean;
  /** 我方连接等待窗口已到期（含 ready 直接 reject 的形态）。 */
  readonly windowExpired: boolean;
  /** 句柄已 dispose。 */
  readonly disposed: boolean;
  /** 该代际曾进入 connected——区分「首连就没成功」与「连上过又掉线」。 */
  readonly everConnected: boolean;
  /** server.reconnect.enabled !== false；为 false 时掉线不再有后台重连，直接 failed。 */
  readonly reconnectEnabled: boolean;
  /** 工具注册面查询：该 id 前缀下是否已有注册工具（输入面 B）。 */
  hasTools(id: string): boolean;
}

/**
 * 六态投影。判据的先后即语义优先级：配置面（disabled）先于运行态；我方拆除（stopped）先于
 * 一切链路信号（旧注册可能尚未注销，工具面此时不可信）；窗口未结束（connecting）先于工具面结果。
 */
export function projectServerState(id: string, input: ServerStateInput): ServerState {
  if (!input.enabled || input.userDisabled) return SERVER_STATES.disabled;
  if (input.tornDown || input.disposed) return SERVER_STATES.stopped;
  if (!input.mountStarted) return SERVER_STATES.stopped;
  if (!input.readySettled) {
    // connecting 纯属我方动作面（发起 mount 到 ready settle 或我方超时之间），与工具面无关。
    return input.windowExpired ? SERVER_STATES.failed : SERVER_STATES.connecting;
  }
  return settledState(input, id);
}

/**
 * ready 已 settle 之后的裁决（第六态投影的最后一段，判据先后即优先级）：
 * 工具前缀命中 → connected；否则曾 connected 且允许重连 → 半确定的 reconnecting（可判时点），
 * 余下是 §3.1 的 failed ①（我方窗口耗尽）或 ②（首连 / 首次发现失败，官方已进后台重连）。
 */
export function settledState(input: ServerStateInput, id: string): ServerState {
  if (input.hasTools(id)) return SERVER_STATES.connected;
  if (!input.everConnected) return SERVER_STATES.failed;
  return input.reconnectEnabled ? SERVER_STATES.reconnecting : SERVER_STATES.failed;
}

/**
 * dsh-mcp-manager — servers/lifecycle/impl/timeout/index.ts：装载等待窗口（§3.4）。
 *
 * 官方把「首连」与「首次 syncTools」串在同一个 connectGeneration 里，且都在 connection.ready
 * 之前完成，所以 ready settle 同时意味着首连与首次发现都已结束（成功或失败）。官方**没有**
 * 连接超时参数——10s 内出结论这个产品语义只能由我方包在句柄等待上。
 *
 * 窗口分两段：
 * 1. `withTimeout(handle.ready, connectTimeoutMs)`；超时投影 failed 并**保留实例不 dispose**
 *    （官方仍在后台退避重连，dispose 等于把常驻重连语义丢掉）。
 * 2. 工具面宽限：官方注册进 ctx.tools 是同步的、且发生在 ready 之前，所以 ready settle 之后
 *    只需再让出一个 tick；一个 tick 后前缀仍为空即 §3.1 的 failed ②。（不按
 *    DISCOVERY_TIMEOUT_MS 轮询：那个预算已经在 ready 内部结算掉了，拿它再等一轮只是让
 *    「首连失败」的结论晚 10s 到达，而结论并不会变。）
 *
 * 晚到结算守卫：dispose 之后、或账本条目已被更新的代际替换之后到达的结算一律丢弃，不再改状态
 * （对齐现状 connectInternal 的代际守卫）。
 */
import { CONNECT_TIMEOUT_MS, DISCOVERY_TIMEOUT_MS } from "../../../../shared/interface.ts";
import { SERVER_STATES } from "../../../../../shared/interface.ts";
import type { ServerState } from "../../../../../shared/interface.ts";
import type { MountedPlugin } from "../../../../shared/interface.ts";
import { diagnosticText } from "../logs/index.ts";
import { lifecyclePorts } from "../service/index.ts";

/** 等待窗口入参：句柄、超时预算与三个只读查询（不自持状态，故本块可纯测）。 */
export interface MountWindowInput {
  /** 账本键 = 交给官方的 serverName；工具注册面按它拼前缀。 */
  readonly id: string;
  readonly handle: MountedPlugin;
  /**
   * 连接等待预算（ms）。缺省取共享层的 CONNECT_TIMEOUT_MS。做成入参而不是在块内写死常量，
   * 是为了让用例用小预算驱动真超时——拿 10s 跑一条超时用例既慢，又把测试挂在真实墙钟上。
   */
  readonly connectTimeoutMs?: number;
  /** 该代际是否仍是账本当前条目：晚到结算据此丢弃。 */
  isCurrent(): boolean;
  /** 工具注册面查询：该 id 前缀下是否已有注册工具。 */
  hasTools(id: string): boolean;
  /**
   * 窗口内收到的官方原文（按到达顺序现读）。
   *
   * 官方是本插件**唯一**的错因来源：成功连接零日志，失败与放弃重连才说话，而宿主默认既不打印
   * 也不落盘——不把原文附进 failed 文案，用户拿到的就只有我方那两段判词。
   */
  diagnostics?(): readonly string[];
  /** 状态投影出口：窗口在起点（connecting）与结算点各回调一次；丢弃的结算不回调。 */
  onState(state: ServerState): void;
}

/** 窗口结算结果：settled 携带最终态，discarded 表示本次结算作废（调用方不得据此改状态）。 */
export type MountWindowOutcome =
  | { readonly kind: "settled"; readonly state: ServerState; readonly error?: string }
  | { readonly kind: "discarded" };

/**
 * 跑完一次装载等待窗口。本函数**不 dispose 任何东西**：连接失败的实例归后台重连，
 * 拆除归调用方的账本动作。
 */
export async function awaitMountWindow(input: MountWindowInput): Promise<MountWindowOutcome> {
  const { withTimeout } = lifecyclePorts.get().pipeline;
  const budgetMs = input.connectTimeoutMs ?? CONNECT_TIMEOUT_MS;
  // 起点先判一次废弃：这一代际若在窗口开始前就已被拆掉或被顶替，点亮 connecting 只会留下一个
  // 「亮了却永不结算」的假状态——本函数之后所有出口都是 discarded、不再回调。此时一个信号都不发，
  // 状态由调用方自己的拆除路径负责。
  if (isAbandoned(input)) return { kind: "discarded" };
  input.onState(SERVER_STATES.connecting);
  let failure: string | undefined;
  try {
    await withTimeout(
      input.handle.ready,
      budgetMs,
      `连接超时（${budgetMs}ms）：官方实例保留不 dispose，仍在后台退避重连`,
    );
  } catch (error) {
    failure = errorText(error);
  }
  if (isAbandoned(input)) return { kind: "discarded" };
  if (failure !== undefined) {
    return settle(input, SERVER_STATES.failed, withOfficialLogs(input, failure));
  }
  if (!input.hasTools(input.id)) {
    await yieldOneTick();
    if (isAbandoned(input)) return { kind: "discarded" };
  }
  if (input.hasTools(input.id)) return settle(input, SERVER_STATES.connected);
  return settle(input, SERVER_STATES.failed, withOfficialLogs(input, missingToolFaceText()));
}

/** 代际守卫判据：句柄已拆，或账本里这一条已被别的代际顶掉。 */
function isAbandoned(input: MountWindowInput): boolean {
  return input.handle.disposed || !input.isCurrent();
}

function settle(input: MountWindowInput, state: ServerState, error?: string): MountWindowOutcome {
  input.onState(state);
  return error === undefined ? { kind: "settled", state } : { kind: "settled", state, error };
}

/**
 * 让出一个 tick。官方注册是同步的且发生在 ready 之前，窗口只需覆盖「ready 的 then 链尚未跑完」
 * 这一小段；这里用宏任务而非微任务，让同一 tick 内排队的其它 then 也先跑完。
 */
function yieldOneTick(): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
}

/**
 * failed 的文案：官方把发现预算（默认 10s）算在 ready 内部，我方只在 ready 之后给一个 tick，
 * 所以这里点名的是官方预算而不是我方等待时长——不这样写会把「谁超时了」记错账。
 */
function missingToolFaceText(): string {
  return `已连接但工具注册面未出现（官方发现预算 ${DISCOVERY_TIMEOUT_MS}ms 已在 ready 内结算）：官方实例在后台重连`;
}

/**
 * failed 文案的统一收尾：把窗口内收到的官方原文接在后面。
 *
 * 只接 failed：connected 说明官方没话说（成功连接零日志），discarded 的结算本就不进状态面，
 * 两处附原文只会把正常路径的文案撑长。
 *
 * 官方一条都没说时返回原文：接一句空的「官方日志：」等于让读的人以为官方说了句空话。
 */
function withOfficialLogs(input: MountWindowInput, text: string): string {
  const diagnostics = input.diagnostics?.();
  const official = diagnostics === undefined ? undefined : diagnosticText(diagnostics);
  return official === undefined ? text : `${text}；${official}`;
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

