    await manager.registerServer({
      name: "cg",
      transport: "stdio",
      command: "codegraph",
      args: ["serve", "--mcp"],
      toolDefinitions: [wrappedTool()],
    });
    await pollUntil(
      "@global 单元虚拟连接建立",
      () => mw.units.get("@global")?.connections.has("cg") === true,
