  it("unavailable → tools 为空", async () => {
    const { manager } = await unavailableBase();
    expect(summarizeOf(manager, manager.projectStore!.find("p1")!, "project").tools).toEqual([]);
  });

  it("unavailable reason 透出到 error", async () => {
