  }

  it("私有 redact 抹掉单元外的 disabled/unconnected 秘密", () => {
    const { mw } = middlewareFixture();
    const out = (mw as unknown as { redact(error: unknown): string }).redact(
      new Error(`fail ${SECRET_MW_DISABLED} ${SECRET_MW_IDLE}`),
